225	            <option value="month">Month</option>
226	          </select>
227	        </label>
228	        <label>
229	          Split by{" "}
230	          <select
231	            value={split}
232	            onChange={(e) => setParam("split", e.target.value)}
233	            className="border border-border rounded px-2 py-1 bg-surface"
234	          >
235	            <option value="none">None</option>
236	            <option value="sentiment">Sentiment</option>
237	            <option value="language">Language</option>
238	            <option value="topic">Topic</option>
239	          </select>
240	        </label>
241	        <label>
242	          View{" "}
243	          <select
244	            value={view}
245	            onChange={(e) => setParam("view", e.target.value)}
246	            className="border border-border rounded px-2 py-1 bg-surface"
247	          >
248	            <option value="chart">Chart</option>
249	            <option value="table">Table</option>
250	          </select>
251	        </label>
252	      </div>
253	      <p className="text-sm text-muted">
254	        {total} articles · {bucket}s start {bucket === "week" ? "Monday" : "day 1"}, UTC
255	      </p>
256	      {split === "topic" && (
257	        <p className="text-sm text-muted">
258	          An article counts under each of its topics, so the bars can add up to more than the total.
259	        </p>
260	      )}
261	      {error && (
262	        <p role="alert" className="text-danger">
263	          {error}
264	        </p>
265	      )}
266	
267	      {view === "chart" && (
268	        <svg
269	          role="img"
