282	                  y -= h;
283	                  const hatch = series === "not_enriched";
284	                  return (
285	                    <a key={series} href={barHref(start, series)} aria-label={`${series}: ${n}`}>
286	                      <rect
287	                        x={x}
288	                        y={y}
289	                        width={32}
290	                        height={h}
291	                        fill={hatch ? "url(#hatch)" : "#2c5f4a"}
292	                        opacity={0.85}
293	                      />
294	                    </a>
295	                  );
296	                })}
297	                <text x={x + 16} y={215} textAnchor="middle" fontSize="9" fill="#6b6a68">
298	                  {start.slice(5, 10)}
299	                </text>
300	              </g>
301	            );
302	          })}
303	          <defs>
304	            <pattern id="hatch" patternUnits="userSpaceOnUse" width="6" height="6">
305	              <path d="M0,6 l6,-6 M-1,1 l2,-2 M5,7 l2,-2" stroke="#6b6a68" strokeWidth="1" />
306	            </pattern>
307	          </defs>
308	        </svg>
309	      )}
310	
311	      <div className={view === "table" ? "" : "sr-only"}>
312	        <table className="w-full text-sm border-collapse">
313	          <thead>
314	            <tr>
315	              <th className="text-left border-b border-border p-2">Bucket</th>
316	              {seriesNames.map((s) => (
317	                <th key={s} className="text-right border-b border-border p-2">
318	                  {s}
319	                </th>
320	              ))}
321	            </tr>
322	          </thead>
323	          <tbody>
324	            {grouped.map(([start, seriesMap]) => (
325	              <tr key={start}>
326	                <td className="p-2 border-b border-border">
327	                  <Link href={barHref(start, null)}>{start.slice(0, 10)}</Link>
328	                </td>
329	                {seriesNames.map((s) => (
330	                  <td key={s} className="p-2 border-b border-border text-right">
331	                    <Link href={barHref(start, s)}>{seriesMap.get(s) ?? 0}</Link>
332	                  </td>
333	                ))}
334	              </tr>
335	            ))}
336	          </tbody>
337	        </table>
338	      </div>
339	    </div>
340	  );
341	}
