"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { parseQuery } from "@/lib/search";
import { FilterBar } from "@/components/FilterBar";
import Link from "next/link";

type Bucket = { bucket_start: string; series: string | null; n: number };

export default function TrendsPage() {
  const sp = useSearchParams();
  const router = useRouter();
  const bucket = sp.get("bucket") === "month" ? "month" : "week";
  const split = sp.get("split") ?? "none";
  const view = sp.get("view") === "table" ? "table" : "chart";
  const [buckets, setBuckets] = useState<Bucket[]>([]);
  const [total, setTotal] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [parseError, setParseError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [debouncing, setDebouncing] = useState(false);
  const urlQ = sp.get("q") ?? "";
  const [qState, setQState] = useState({ value: urlQ, synced: urlQ });
  if (qState.synced !== urlQ) {
    setQState({ value: urlQ, synced: urlQ });
  }
  const q = qState.value;
  const setQ = (value: string) => setQState((s) => ({ ...s, value }));
  const abortRef = useRef<AbortController | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const seq = useRef(0);

  useEffect(() => {
    const my = ++seq.current;
    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;
    setLoading(true);
    const url = new URL("/api/aggregate", window.location.origin);
    url.searchParams.set("q", sp.get("q") ?? "");
    url.searchParams.set("bucket", bucket);
    url.searchParams.set("split", split);
    for (const k of ["from", "to"] as const) {
      const v = sp.get(k);
      if (v) url.searchParams.set(k, v);
    }
    for (const k of ["source", "lang", "sentiment", "topic"] as const) {
      for (const v of sp.getAll(k)) url.searchParams.append(k, v);
    }
    void fetch(url, { signal: ac.signal })
      .then(async (r) => {
        const j = await r.json();
        if (my !== seq.current) return;
        if (!r.ok) {
          setError(j.error?.message ?? "Aggregate failed");
          return;
        }
        setError(null);
        setBuckets(j.buckets ?? []);
        setTotal(j.total ?? 0);
      })
      .catch((e) => {
        if ((e as Error).name === "AbortError") return;
        if (my !== seq.current) return;
        setError("Aggregate failed");
      })
      .finally(() => {
        if (my === seq.current) setLoading(false);
      });
  }, [sp, bucket, split]);

  const grouped = useMemo(() => {
    const map = new Map<string, Map<string, number>>();
    for (const b of buckets) {
      const key = String(b.bucket_start);
      if (!map.has(key)) map.set(key, new Map());
      map.get(key)!.set(b.series ?? "total", b.n);
    }
    return [...map.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  }, [buckets]);

  const maxN = Math.max(1, ...buckets.map((b) => b.n));
  const seriesNames = [
    ...new Set(buckets.map((b) => b.series ?? "total").filter((s) => s !== null)),
  ];

  function clearDebounce() {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
      debounceRef.current = null;
    }
    setDebouncing(false);
  }

  function submit(nextQ: string) {
    clearDebounce();
    const r = parseQuery(nextQ);
    if (!r.ok) {
      setParseError(r.error.message);
      return;
    }
    setParseError(null);
    const p = new URLSearchParams(sp.toString());
    if (nextQ) p.set("q", nextQ);
    else p.delete("q");
    const next = p.toString();
    if (next === sp.toString()) return;
    router.push(`/trends?${next}`);
  }

  useEffect(() => {
    if (q === urlQ) {
      clearDebounce();
      setParseError(null);
      return;
    }
    const r = parseQuery(q);
    if (!r.ok) {
      clearDebounce();
      setParseError(r.error.message);
      return;
    }
    setParseError(null);
    setDebouncing(true);
    debounceRef.current = setTimeout(() => {
      debounceRef.current = null;
      setDebouncing(false);
      submit(q);
    }, 500);
    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
        debounceRef.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q, urlQ]);

  const fieldBusy = loading || debouncing;

  function setParam(key: string, value: string) {
    const p = new URLSearchParams(sp.toString());
    p.set(key, value);
    router.replace(`/trends?${p.toString()}`);
  }

  function barHref(start: string, series: string | null) {
    const startDate = new Date(start);
    const end = new Date(startDate);
    if (bucket === "week") end.setUTCDate(end.getUTCDate() + 7);
    else end.setUTCMonth(end.getUTCMonth() + 1);
    const p = new URLSearchParams(sp.toString());
    p.set("from", startDate.toISOString().slice(0, 10));
    p.set("to", end.toISOString().slice(0, 10));
    if (series && series !== "total" && series !== "not_enriched") {
      if (split === "sentiment") p.set("sentiment", series);
      if (split === "topic") p.set("topic", series);
      if (split === "language") p.set("lang", series);
    }
    if (series === "not_enriched") {
      if (split === "sentiment") p.set("sentiment", "not_enriched");
      if (split === "topic") p.set("topic", "not_enriched");
    }
    p.delete("bucket");
    p.delete("split");
    p.delete("view");
    return `/?${p.toString()}`;
  }

  return (
    <div className="space-y-4">
      <h1 className="text-xl font-semibold">Trends</h1>
      <div className="relative">
        <input
          className="w-full border border-border rounded px-3 py-2 pr-9 bg-surface"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") submit(q);
          }}
          aria-invalid={!!parseError}
          aria-busy={fieldBusy}
          dir="auto"
        />
        {fieldBusy && (
          <span
            className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-muted"
            aria-hidden
          >
            <svg className="h-4 w-4 animate-spin" viewBox="0 0 16 16" fill="none">
              <circle
                cx="8"
                cy="8"
                r="6"
                stroke="currentColor"
                strokeOpacity="0.25"
                strokeWidth="2"
              />
              <path
                d="M14 8a6 6 0 0 0-6-6"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
          </span>
        )}
      </div>
      {parseError && (
        <p className="text-sm text-danger" role="alert">
          {parseError}
        </p>
      )}
      <FilterBar />
      <div className="flex flex-wrap gap-3 text-sm">
        <label>
          Bucket{" "}
          <select
            value={bucket}
            onChange={(e) => setParam("bucket", e.target.value)}
            className="border border-border rounded px-2 py-1 bg-surface"
          >
            <option value="week">Week</option>
            <option value="month">Month</option>
          </select>
        </label>
        <label>
          Split by{" "}
          <select
            value={split}
            onChange={(e) => setParam("split", e.target.value)}
            className="border border-border rounded px-2 py-1 bg-surface"
          >
            <option value="none">None</option>
            <option value="sentiment">Sentiment</option>
            <option value="language">Language</option>
            <option value="topic">Topic</option>
          </select>
        </label>
        <label>
          View{" "}
          <select
            value={view}
            onChange={(e) => setParam("view", e.target.value)}
            className="border border-border rounded px-2 py-1 bg-surface"
          >
            <option value="chart">Chart</option>
            <option value="table">Table</option>
          </select>
        </label>
      </div>
      <p className="text-sm text-muted">
        {total} articles · {bucket}s start {bucket === "week" ? "Monday" : "day 1"}, UTC
      </p>
      {split === "topic" && (
        <p className="text-sm text-muted">
          An article counts under each of its topics, so the bars can add up to more than the total.
        </p>
      )}
      {error && (
        <p role="alert" className="text-danger">
          {error}
        </p>
      )}

      {view === "chart" && (
        <svg
          role="img"
          aria-label={`Bar chart of article counts by ${bucket}`}
          viewBox={`0 0 ${Math.max(400, grouped.length * 48)} 220`}
          className="w-full max-w-full border border-border bg-surface"
        >
          {grouped.map(([start, seriesMap], i) => {
            const x = 40 + i * 48;
            let y = 200;
            const entries = [...seriesMap.entries()];
            return (
              <g key={start}>
                {entries.map(([series, n]) => {
                  const h = (n / maxN) * 160;
                  y -= h;
                  const hatch = series === "not_enriched";
                  return (
                    <a key={series} href={barHref(start, series)} aria-label={`${series}: ${n}`}>
                      <rect
                        x={x}
                        y={y}
                        width={32}
                        height={h}
                        fill={hatch ? "url(#hatch)" : "#2c5f4a"}
                        opacity={0.85}
                      />
                    </a>
                  );
                })}
                <text x={x + 16} y={215} textAnchor="middle" fontSize="9" fill="#6b6a68">
                  {start.slice(5, 10)}
                </text>
              </g>
            );
          })}
          <defs>
            <pattern id="hatch" patternUnits="userSpaceOnUse" width="6" height="6">
              <path d="M0,6 l6,-6 M-1,1 l2,-2 M5,7 l2,-2" stroke="#6b6a68" strokeWidth="1" />
            </pattern>
          </defs>
        </svg>
      )}

      <div className={view === "table" ? "" : "sr-only"}>
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr>
              <th className="text-left border-b border-border p-2">Bucket</th>
              {seriesNames.map((s) => (
                <th key={s} className="text-right border-b border-border p-2">
                  {s}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {grouped.map(([start, seriesMap]) => (
              <tr key={start}>
                <td className="p-2 border-b border-border">
                  <Link href={barHref(start, null)}>{start.slice(0, 10)}</Link>
                </td>
                {seriesNames.map((s) => (
                  <td key={s} className="p-2 border-b border-border text-right">
                    <Link href={barHref(start, s)}>{seriesMap.get(s) ?? 0}</Link>
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

