11	export default function TrendsPage() {
12	  const sp = useSearchParams();
13	  const router = useRouter();
14	  const bucket = sp.get("bucket") === "month" ? "month" : "week";
15	  const split = sp.get("split") ?? "none";
16	  const view = sp.get("view") === "table" ? "table" : "chart";
17	  const [buckets, setBuckets] = useState<Bucket[]>([]);
18	  const [total, setTotal] = useState(0);
19	  const [error, setError] = useState<string | null>(null);
20	  const [parseError, setParseError] = useState<string | null>(null);
21	  const [loading, setLoading] = useState(false);
22	  const [debouncing, setDebouncing] = useState(false);
23	  const urlQ = sp.get("q") ?? "";
