146	  }
147	
148	  function barHref(start: string, series: string | null) {
149	    const startDate = new Date(start);
150	    const end = new Date(startDate);
151	    if (bucket === "week") end.setUTCDate(end.getUTCDate() + 7);
152	    else end.setUTCMonth(end.getUTCMonth() + 1);
153	    const p = new URLSearchParams(sp.toString());
154	    p.set("from", startDate.toISOString().slice(0, 10));
155	    p.set("to", end.toISOString().slice(0, 10));
156	    if (series && series !== "total" && series !== "not_enriched") {
157	      if (split === "sentiment") p.set("sentiment", series);
158	      if (split === "topic") p.set("topic", series);
159	      if (split === "language") p.set("lang", series);
160	    }
161	    if (series === "not_enriched") {
162	      if (split === "sentiment") p.set("sentiment", "not_enriched");
163	      if (split === "topic") p.set("topic", "not_enriched");
164	    }
165	    p.delete("bucket");
