1	import { getConfig } from "@/lib/config";
2	import { getWebPool } from "@/lib/db/pool";
3	import { parseQuery, compileAst, echoAst, buildFilterClauses, parseDateParam } from "@/lib/search";
4	import type { SearchFilters } from "@/lib/search/filters";
5	
6	export const dynamic = "force-dynamic";
7	
8	export async function GET(req: Request) {
9	  const url = new URL(req.url);
10	  const q = url.searchParams.get("q") ?? "";
11	  const bucket = url.searchParams.get("bucket") === "month" ? "month" : "week";
12	  const split = url.searchParams.get("split") ?? "none";
13	  const from = parseDateParam(url.searchParams.get("from"), "from");
14	  const to = parseDateParam(url.searchParams.get("to"), "to");
15	
16	  const filters: SearchFilters = {
17	    ...(from ? { from } : {}),
18	    ...(to ? { to } : {}),
19	    ...(url.searchParams.getAll("source").length
20	      ? { sources: url.searchParams.getAll("source") }
21	      : {}),
22	    ...(url.searchParams.getAll("lang").length
23	      ? { languages: url.searchParams.getAll("lang") }
24	      : {}),
25	    ...(url.searchParams.getAll("sentiment").length
26	      ? { sentiments: url.searchParams.getAll("sentiment") }
27	      : {}),
28	    ...(url.searchParams.getAll("topic").length
29	      ? { topics: url.searchParams.getAll("topic") }
30	      : {}),
31	  };
32	
33	  const parsed = parseQuery(q);
34	  if (!parsed.ok) {
35	    return Response.json({ error: parsed.error }, { status: 400 });
36	  }
37	
38	  const compiled = compileAst(parsed.ast, 1);
39	  const fb = buildFilterClauses(filters, compiled.params.length + 1);
40	  const whereParts: string[] = [];
41	  if (compiled.sql) whereParts.push(`(${compiled.sql})`);
42	  whereParts.push(...fb.clauses);
43	  const where = whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "WHERE true";
44	  const params = [...compiled.params, ...fb.params];
45	
46	  const trunc = bucket === "month" ? "month" : "week";
47	  const config = getConfig();
48	  const pool = getWebPool(config.db);
49	
50	  // Cap buckets
51	  const bounds = await pool.query<{ lo: string | null; hi: string | null }>(
52	      `WITH f AS (SELECT a.published_at FROM articles a ${where})
53	       SELECT min(published_at)::text AS lo, max(published_at)::text AS hi FROM f`,
54	      params,
55	    );
56	    const lo = from ?? (bounds.rows[0]?.lo ? new Date(bounds.rows[0].lo) : null);
57	    const hi = to ?? (bounds.rows[0]?.hi ? new Date(new Date(bounds.rows[0].hi).getTime() + 1) : null);
58	    if (lo && hi) {
59	      const ms = hi.getTime() - lo.getTime();
60	      const bucketMs = bucket === "month" ? 30 * 86400_000 : 7 * 86400_000;
